SELECT
    d.country_code AS countryCode,
    d.indicator_code AS indicatorCode,
    d.year AS year,
    d.`value` AS value
FROM t_wdi_data d
WHERE d.country_code IN

    #{cc}

AND d.indicator_code IN

    #{ic}


    AND d.year >= #{startYear}


    AND d.year <= #{endYear}

ORDER BY d.country_code, d.indicator_code, d.year
LIMIT #{maxRows}

SELECT
    f.country_code AS countryCode,
    f.series_code AS seriesCode,
    f.year AS year,
    f.footnote_text AS footnoteText,
    f.footnote_text_cn AS footnoteTextCn
FROM t_wdi_footnote f
WHERE f.country_code IN

    #{cc}

AND f.series_code IN

    #{sc}


    AND f.year >= #{startYear}


    AND f.year <= #{endYear}

ORDER BY f.country_code, f.series_code, f.year
LIMIT #{maxRows}
